/**
 * @method
 * @name tx_fnPopUpFeeReport
 * @description fn Pop Up Fee Report 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnPopUpFeeReport = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_fnPopUpFeeReportReq") ? $c.util.getComponent("dma_fnPopUpFeeReportReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
