///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name __on_enter_4_ipt_efreqisunm
 * @description on enter 4 ipt efreqisunm 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_4_ipt_efreqisunm = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.searchList() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf35000.__on_enter_4_ipt_efReqIsuNm' }); }
};

/**
 * @method
 * @name grd_result_fmt_bndApplId
 * @description grd result fmt bnd Appl Id 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_fmt_bndApplId = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_result");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "bndMktactTpCd") ?? '') : '');
        if (v !== '000') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "bndApplId") : '') ?? '') + '</a>'; }
        return String((dl && dl.getCellData ? dl.getCellData(r, "bndApplId") : '') ?? '');
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_result.bndApplId" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_result_fmt_stdCd
 * @description grd result fmt std Cd 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_fmt_stdCd = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_result");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "nusualBndTpCd") ?? '') : '');
        if (['3','4'].indexOf(v) >= 0) { return String((dl && dl.getCellData ? dl.getCellData(r, "stdCd") : '') ?? ''); }
        return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "stdCd") : '') ?? '') + '</a>';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_result.stdCd" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_result_fmt_applYn
 * @description grd result fmt appl Yn 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_fmt_applYn = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_result");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "applYn") ?? '') : '');
        if (v === '반송') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "applYn") : '') ?? '') + '</a>'; }
        return String((dl && dl.getCellData ? dl.getCellData(r, "applYn") : '') ?? '');
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_result.applYn" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_result_fillAct
 * @description grd result fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.fillAct' });
    }
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @param {*} div div
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function (div) {
    if (div === 'button') {
        $c.util.getComponent('dma_searchListReq').set('pageIndex', "1");
    }
    $c.util.getComponent('dma_searchListReq').set('method', "resultSearch");
    await scwin.tx_fn_searchList('/result/result.do');
};

/**
 * @method
 * @name OpenReqView
 * @description Open Req View 처리
 * @param {*} bnd_appl_id bnd_appl_id
 * @param {*} bnd_list_procs_tp_cd bnd_list_procs_tp_cd
 * @param {*} bnd_mktact_tp_cd bnd_mktact_tp_cd
 * @param {*} bkbnd_tp_cd bkbnd_tp_cd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.OpenReqView = async function (bnd_appl_id, bnd_list_procs_tp_cd, bnd_mktact_tp_cd, bkbnd_tp_cd) {
    if (bnd_list_procs_tp_cd === '1' || bnd_list_procs_tp_cd === '2') {
        bnd_list_procs_tp_cd = "1";
    }
    scwin.fm = (document.SearchForm || { elements: [] });
    let _previewWindow;
    let width;
    let height;
    if (bnd_mktact_tp_cd.substr(0, 1) === 1) {
        if (bnd_mktact_tp_cd.substr(2, 1) === 1) {
            width = 900;
            height = 700;
        } else {
            if (bnd_mktact_tp_cd.substr(2, 1) === 2) {
                if (bkbnd_tp_cd === '2' || bkbnd_tp_cd === '3') {
                    width = 900;
                    height = 700;
                } else {
                    width = 900;
                    height = 700;
                }
            } else {
                if (bnd_mktact_tp_cd === '113') {
                    width = 900;
                    height = 700;
                }
            }
        }
    } else {
        if (bnd_mktact_tp_cd === '201' || bnd_mktact_tp_cd === '302' || bnd_mktact_tp_cd === '401') {
            width = 900;
            height = 750;
        } else {
            if (bnd_mktact_tp_cd === '402') {
                width = 1000;
                height = 800;
            } else {
                width = 900;
                height = 680;
            }
        }
    }
    const mtWidth = document.body.clientWidth;
    const mtHeight = document.body.clientHeight;
    const scX = 0;
    const scY = 0;
    const popX = scX + (mtWidth - width) / 2;
    const popY = scY + (mtHeight - height) / 2;
    if (bnd_mktact_tp_cd.substr(0, 1) === 1) {
        if (bnd_mktact_tp_cd.substr(2, 1) === 1) {
            // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
            _previewWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/result/result.do", unresolved: "nav:" + "/result/result.do" }; })();
            $c.util.getComponent("dma_searchListReq").set("bndApplId", bnd_appl_id);
            $c.util.getComponent("dma_searchListReq").set("bndListProcsTpCd", bnd_list_procs_tp_cd);
            $c.util.getComponent("dma_searchListReq").set("bndMktactTpCd", bnd_mktact_tp_cd);
            $c.util.getComponent('dma_searchListReq').set('method', 'popupListeachView');
            scwin.fm.action = '/result/result.do';

        } else {
            if (bnd_mktact_tp_cd.substr(2, 1) === 2) {
