/**
 * @method
 * @name addFile
 * @description add File 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.addFile = async function () {
    (($c.util.getComponent('inputContainer')) && ($c.util.getComponent('inputContainer')).removeAll ? ($c.util.getComponent('inputContainer')).removeAll() : (($c.util.getComponent('inputContainer')) && ($c.util.getComponent('inputContainer')).setValue ? ($c.util.getComponent('inputContainer')).setValue('') : void 0));
    const bndApplIdArr = [];
    const isuNmArray = [];
    const checkedBoxes = $(".row-checkbox:checked");
    checkedBoxes.each(function() {
            const bnd_appl_id = $(this).val();
            const isu_nm = $(this).closest('tr').find("td:eq(3)").text();
            const mktact_nm = $(this).closest('tr').find("td:eq(4)").text();
            bndApplIdArr.push(bnd_appl_id);
            isuNmArray.push("[" + isu_nm + " / " + mktact_nm + "]");
    });
    if (bndApplIdArr.length === 0) {
        await $c.win.alert("파일 추가 대상을 선택하세요.\n(멀티 선택이 가능합니다.)");
        return;
    }
    const confirmMsg = isuNmArray.join("\n") + "\n\n선택한 종목에 파일을 추가하시겠습니까?";
    if (!await $c.win.confirm(confirmMsg)) {
        return false;
    }
    for (let i = 0; i < bndApplIdArr.length; i++) {
        $("#inputContainer").append("<input type='hidden' name='bnd_appl_id_list' value='" + bndApplIdArr[i] + "'>");
    }
    scwin.fm = (document.SearchForm || { elements: [] });
    const width = 970;
    const height = 500;
    const mtWidth = document.body.clientWidth;
    const mtHeight = document.body.clientHeight;
    const scX = 0;
    const scY = 0;
    const popX = scX + (mtWidth - width) / 2;
    const popY = scY + (mtHeight - height) / 2;
