    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    _previewWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/result/result.do?ipt_method_2=popupAttachedFileAdd", unresolved: "nav:" + "/result/result.do?ipt_method_2=popupAttachedFileAdd" }; })();
    scwin.fm.action = '/result/result.do?method=popupAttachedFileAdd';

};

